val previousModel = remember(context, previousImage, previousReport) {
    ScreenshotRequestFactory.createRequest(context, previousImage, previousReport) ?: previousImage
}

var detailedResult by remember { mutableStateOf<DetailedImageComparator.DetailedComparisonResult?>(null) }
var isCalculatingDetail by remember { mutableStateOf(false) }

LaunchedEffect(currentImage, previousImage, isCurrentDynamicallyExpired, isPreviousDynamicallyExpired) {
    if (currentImage != null && !previousImage.isNullOrBlank() &&
        !isCurrentDynamicallyExpired && !isPreviousDynamicallyExpired
    ) {
        isCalculatingDetail = true
        detailedResult = null
        var localB1: Bitmap? = null
        try {
            val b1 = when (currentImage) {
                is Bitmap -> if (!currentImage.isRecycled) currentImage else null
                is String -> ScreenshotManager.getOrFetchBitmap(context, currentImage, "compare_detailed", currentReport)
                is android.net.Uri -> {
                    localB1 = try {
                        context.contentResolver.openInputStream(currentImage)?.use { stream ->
                            android.graphics.BitmapFactory.decodeStream(stream)
                        }
                    } catch (_: Exception) { null }
                    localB1
                }
                else -> null
            }
            val b2 = ScreenshotManager.getOrFetchBitmap(context, previousImage, "compare_detailed", previousReport)
            if (b1 != null && b2 != null) {
                val isSameUrl = (currentImage is String && currentImage == previousImage)
                detailedResult = DetailedImageComparator.compareBitmaps(b1, b2, isSameUrl)
            }
        } catch (ce: CancellationException) {
            throw ce
        } catch (_: Exception) {
            detailedResult = null
        } finally {
            localB1?.recycle()
            isCalculatingDetail = false
        }
    } else {
        detailedResult = null
        isCalculatingDetail = false
    }
}

